/**
 * The identity provider stub's key material.
 *
 * openid-client refuses plain-HTTP issuers, so the stub serves TLS. The
 * certificate is self-signed (its own CA) and the suite trusts it through
 * NODE_EXTRA_CA_CERTS, which Bun reads at process start — the fixture is
 * therefore generated by `scripts/oidc-fixture.ts` before the suite runs
 * and reused from then on, so the issuer and the published key stay
 * stable for the whole run.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import * as jose from "jose";

export const OIDC_FIXTURE_DIR = join(tmpdir(), "sentry-e2e-oidc");
export const OIDC_CERT_PATH = join(OIDC_FIXTURE_DIR, "cert.pem");
export const OIDC_KEY_PATH = join(OIDC_FIXTURE_DIR, "key.pem");
export const OIDC_SIGNING_PRIVATE_PATH = join(
  OIDC_FIXTURE_DIR,
  "signing-private.jwk",
);
export const OIDC_SIGNING_PUBLIC_PATH = join(
  OIDC_FIXTURE_DIR,
  "signing-public.jwk",
);
export const OIDC_PORT_PATH = join(OIDC_FIXTURE_DIR, "port");

export function ensureFixtureDir(): void {
  mkdirSync(OIDC_FIXTURE_DIR, { recursive: true });
}

/** The TLS certificate for the stub; a self-signed certificate is its own CA. */
export function ensureCertificate(): { cert: string; key: string } {
  ensureFixtureDir();
  if (!existsSync(OIDC_CERT_PATH) || !existsSync(OIDC_KEY_PATH)) {
    const result = Bun.spawnSync([
      "openssl",
      "req",
      "-x509",
      "-newkey",
      "rsa:2048",
      "-keyout",
      OIDC_KEY_PATH,
      "-out",
      OIDC_CERT_PATH,
      "-days",
      "3650",
      "-nodes",
      "-subj",
      "/CN=localhost",
      "-addext",
      "subjectAltName=DNS:localhost,IP:127.0.0.1",
    ]);
    if (!result.success) {
      throw new Error("The OIDC stub needs openssl to generate its certificate");
    }
  }
  return {
    cert: readFileSync(OIDC_CERT_PATH, "utf8"),
    key: readFileSync(OIDC_KEY_PATH, "utf8"),
  };
}

/** The signing key pair, persisted so the published JWKS stays valid. */
export async function ensureSigningKey(): Promise<CryptoKey> {
  ensureFixtureDir();
  if (
    !existsSync(OIDC_SIGNING_PRIVATE_PATH) ||
    !existsSync(OIDC_SIGNING_PUBLIC_PATH)
  ) {
    const pair = await jose.generateKeyPair("RS256", { extractable: true });
    writeFileSync(
      OIDC_SIGNING_PRIVATE_PATH,
      JSON.stringify(await jose.exportJWK(pair.privateKey)),
    );
    writeFileSync(
      OIDC_SIGNING_PUBLIC_PATH,
      JSON.stringify(await jose.exportJWK(pair.publicKey)),
    );
  }
  return (await jose.importJWK(
    JSON.parse(readFileSync(OIDC_SIGNING_PRIVATE_PATH, "utf8")) as jose.JWK,
    "RS256",
  )) as CryptoKey;
}

/** The published JWK (the stub's `/jwks`). */
export function readPublicJwk(): Record<string, unknown> {
  return {
    ...(JSON.parse(
      readFileSync(OIDC_SIGNING_PUBLIC_PATH, "utf8"),
    ) as Record<string, unknown>),
    kid: "e2e-key",
    alg: "RS256",
    use: "sig",
  };
}

/** The port is persisted so the issuer stays stable across the run. */
export function resolvePort(): number {
  ensureFixtureDir();
  if (existsSync(OIDC_PORT_PATH)) {
    return Number(readFileSync(OIDC_PORT_PATH, "utf8"));
  }
  const port = Number(process.env.E2E_OIDC_PORT ?? 9443);
  writeFileSync(OIDC_PORT_PATH, String(port));
  return port;
}

export function persistPort(port: number): void {
  ensureFixtureDir();
  writeFileSync(OIDC_PORT_PATH, String(port));
}
